{
  "countries": [
    {
      "code": "NZ",
      "languages": ["English (英語)", "Māori (マオリ語)"],
      "plate_note": "ナンバープレートは前面が白・背面が黄色で、黒の文字・3文字＋3数字（例 ABC 123）。左端に小さなニュージーランド国旗ロゴが付く。",
      "scripts": ["latin"],
      "traffic_side": "left"
    },
    {
      "code": "US",
      "languages": ["English (英語)"],
      "plate_note": "州ごとにデザイン・形式が異なるが、基本は白地に黒文字の 1〜7 桁の英数字。州名・ロゴ・年号が入ることが多い。",
      "scripts": ["latin"],
      "traffic_side": "right"
    },
    {
      "code": "CA",
      "languages": ["English (英語)", "French (フランス語)"],
      "plate_note": "各州・準州が独自デザイン。省略せずに「Ontario」や「Québec」などの州名とスローガンが入る。文字は黒か白で、白地に黒文字が一般的。形式は 1〜4 文字＋数字（例 AB 1234）。",
      "scripts": ["latin"],
      "traffic_side": "right"
    },
    {
      "code": "MX",
      "languages": ["Spanish (スペイン語)"],
      "plate_note": "2016 年以降は全国統一デザイン。白地に黒文字の 3 文字＋3 数字（例 ABC‑123）。左上にメキシコ国章、右側に州名と州の紋章が入る。",
      "scripts": ["latin"],
      "traffic_side": "right"
    },
    {
      "code": "GT",
      "languages": ["Spanish (スペイン語)"],
      "plate_note": "白地に黒文字。県名を表す 2 文字のプレフィックス＋4 桁の数字（例 GT 1234）。左側に「GUATEMALA」の文字と国章がある。",
      "scripts": ["latin"],
      "traffic_side": "right"
    },
    {
      "code": "CR",
      "languages": ["Spanish (スペイン語)"],
      "plate_note": "白底に黒文字。3 文字＋3 数字または 2 文字＋4 数字の形式（例 ABC 123、CR‑1234）。左上に「CR」マークと省略した県コードが表示される。",
      "scripts": ["latin"],
      "traffic_side": "right"
    }
  ]
}
